impl SceneBuilder {
    pub fn new(
        source: SourceOwner,
        animation: OwnedAnimation,
        generation: u64,
        viewport: Viewport,
        limits: Limits,
    ) -> Result<Self> {
        let limits = limits.effective();
        if !std::sync::Arc::ptr_eq(&source, animation.source_owner()) {
            return Err(invalid(0));
        }
        if source.len() > limits.source_bytes {
            return Err(limit(LimitKind::SourceBytes));
        }
        crate::validate::viewport(viewport)?;
        let live = animation.storage_bytes().ok_or_else(arithmetic)?;
        if live > limits.reserved_bytes {
            return Err(limit(LimitKind::ReservedBytes));
        }
        let owner = NEXT_OWNER
            .try_update(Ordering::Relaxed, Ordering::Relaxed, |v| v.checked_add(1))
            .map_err(|_| arithmetic())?;
        let root = SceneId {
            owner,
            slot: 0,
            serial: 1,
        };
        let mut value = Self {
            owner,
            source,
            generation,
            scenes: Vec::new(),
            animation,
            ignored: [Ignored::default(); 4],
            stats: MemoryStats {
                source_bytes: live,
                live_bytes: live,
                peak_live_bytes: live,
                total_allocated_bytes: 0,
                allocation_count: 0,
            },
            limits,
            drafts: [None; 64],
            draft_depth: 0,
            next_serial: 1,
            root,
        };
        value.stats.source_bytes = value.source.capacity();
        let actual = value.reserve_scene()?;
        value.scenes.push(SceneData::new(actual.serial, viewport));
        value.root = actual;
        Ok(value)
    }
    fn reserve_scene(&mut self) -> Result<SceneId> {
        let serial = self.serial()?;
        let available = self
            .limits
            .reserved_bytes
            .checked_sub(self.stats.live_bytes)
            .ok_or_else(|| limit(LimitKind::ReservedBytes))?;
        if self.stats.allocation_count == usize::MAX {
            return Err(arithmetic());
        }
        let (new, old) = reserve(
            &mut self.scenes,
            1,
            self.limits.scenes,
            available.min(usize::MAX - self.stats.total_allocated_bytes),
        )?;
        if new != 0 {
            self.stats.peak_live_bytes = self
                .stats
                .peak_live_bytes
                .max(add(self.stats.live_bytes, new)?);
            self.stats.live_bytes = add(self.stats.live_bytes - old, new)?;
            self.stats.total_allocated_bytes = add(self.stats.total_allocated_bytes, new)?;
            self.stats.allocation_count += 1;
        }
        Ok(SceneId {
            owner: self.owner,
            slot: self.scenes.len() as u32,
            serial,
        })
    }
    pub(crate) fn serial(&mut self) -> Result<u64> {
        let serial = self.next_serial;
        self.next_serial = self.next_serial.checked_add(1).ok_or_else(arithmetic)?;
        Ok(serial)
    }
    pub(crate) fn index(&self, id: SceneId) -> Result<usize> {
        let scene = self.scenes.get(id.index()).ok_or_else(|| invalid(0))?;
        if id.owner != self.owner || id.serial != scene.serial {
            return Err(invalid(0));
        }
        Ok(id.index())
    }
    pub(crate) fn writable(&self, id: SceneId) -> Result<usize> {
        let index = self.index(id)?;
        if self.scenes[index].sealed || self.active_draft().is_some_and(|draft| draft.scene != id) {
            return Err(invalid(0));
        }
        Ok(index)
    }
    pub fn source_owner(&self) -> &SourceOwner {
        &self.source
    }
    pub fn root_id(&self) -> SceneId {
        self.root
    }
    pub fn scene(&self, id: SceneId) -> Result<SceneView<'_>> {
        let i = self.index(id)?;
        Ok(self.scenes[i].view(
            self.owner,
            i,
            &self.scenes,
            &self.source,
            self.animation.view(),
            self.ignored,
        ))
    }
    pub fn memory_stats(&self) -> MemoryStats {
        self.stats
    }
    pub fn new_scene(&mut self, viewport: Viewport) -> Result<SceneId> {
        crate::validate::viewport(viewport)?;
        let id = self.reserve_scene()?;
        self.scenes.push(SceneData::new(id.serial, viewport));
        Ok(id)
    }
    pub fn mark(&self, scene: SceneId) -> Result<BuildMark> {
        if self.draft_depth != 0 {
            return Err(invalid(0));
        }
        self.checkpoint_internal(scene)
    }
    pub(crate) fn checkpoint_internal(&self, scene: SceneId) -> Result<BuildMark> {
        self.writable(scene)?;
        self.checkpoint_unrestricted(scene)
    }
    pub(crate) fn checkpoint_unrestricted(&self, scene: SceneId) -> Result<BuildMark> {
        let i = self.index(scene)?;
        Ok(BuildMark {
            scene,
            epoch: self.scenes[i].epoch,
            image_pixels: self.scenes[i].image_pixels,
            lengths: self.scenes[i].lengths(),
        })
    }
    pub fn rollback(&mut self, mark: BuildMark) -> Result<()> {
        if self.draft_depth != 0 {
            return Err(invalid(0));
        }
        self.rollback_internal(mark)
    }
use crate::builder::room;
use crate::memory::{add, bytes};
use crate::types::{invalid, limit, stopped};
use crate::*;
impl SceneBuilder {
    pub fn append_shape(
        &mut self,
        scene: SceneId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<ShapeId> {
        let i = self.writable(scene)?;
        control.checkpoint().map_err(stopped)?;
        if input.path.edges.len() != input.edge_colors.len() {
            return Err(invalid(0));
        }
        crate::validate::shape_attributes(self, scene, &input.shape, control)?;
        crate::validate::path(&self.source, &input.path, control)?;
        let s = &self.scenes[i];
        for (len, extra, cap, kind) in [
            (s.shapes.len(), 1, self.limits.shapes, LimitKind::Shapes),
            (
                s.edges.len(),
                input.path.edges.len(),
                self.limits.edges,
                LimitKind::Edges,
            ),
            (
                s.path_segments.len(),
                input.path.segments.len(),
                self.limits.commands,
                LimitKind::PathCommands,
            ),
            (
                s.path_numbers.len(),
                input.path.numbers.len(),
                self.limits.numbers,
                LimitKind::PathNumbers,
            ),
        ] {
            if add(len, extra)? > cap {
                return Err(limit(kind));
            }
        }
        let pending = add(
            add(
                add(bytes(&input.path.edges)?, bytes(&input.path.subpaths)?)?,
                add(bytes(&input.path.segments)?, bytes(&input.path.numbers)?)?,
            )?,
            bytes(&input.edge_colors)?,
        )?;
        self.pending(pending)?;
        let serial = self.serial()?;
        room!(self, i, shapes, 1, self.limits.shapes, pending);
        room!(self, i, shapes_serials, 1, self.limits.shapes, pending);
        room!(
            self,
            i,
            edges,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_colors,
            input.edge_colors.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            edge_shape_ids,
            input.path.edges.len(),
            self.limits.edges,
            pending
        );
        room!(
            self,
            i,
            path_subpaths,
            input.path.subpaths.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_segments,
            input.path.segments.len(),
            self.limits.commands,
            pending
        );
        room!(
            self,
            i,
            path_numbers,
            input.path.numbers.len(),
            self.limits.numbers,
            pending
        );
        let mark = self.checkpoint_internal(scene)?;
        let id = ShapeId {
            owner: self.owner,
            scene: scene.slot,
            slot: self.scenes[i].shapes.len() as u32,
            serial,
        };
        let result = self.publish_shape(i, id, input, control);
        if result.is_err() {
            self.rollback_internal(mark)?;
        }
        result.map(|()| id)
    }
    fn publish_shape(
        &mut self,
        i: usize,
        id: ShapeId,
        input: ShapeInput,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let scene = &mut self.scenes[i];
        let edge_first = scene.edges.len();
        let number_first = scene.path_numbers.len();
        let mut shape = input.shape;
        shape.edges = TableRange {
            first: edge_first,
            count: input.path.edges.len(),
        };
        shape.subpaths = TableRange {
            first: scene.path_subpaths.len(),
            count: input.path.subpaths.len(),
        };
        for (edge, color) in input.path.edges.into_iter().zip(input.edge_colors) {
            control.charge(WorkKind::Edge, 1).map_err(stopped)?;
            scene.edges.push(edge);
            scene.edge_colors.push(color);
            scene.edge_shape_ids.push(id.slot);
        }
        for mut subpath in input.path.subpaths {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            subpath.first_edge = add(subpath.first_edge, edge_first)?;
            scene.path_subpaths.push(subpath);
        }
        for mut path in input.path.segments {
            control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
            path.first_edge = add(path.first_edge, edge_first)?;
            path.first_number = add(path.first_number, number_first)?;
            scene
                .path_segments
                .push(ScenePathSegment { path, shape: id });
        }
        for number in input.path.numbers {
            control.charge(WorkKind::SourceRead, 1).map_err(stopped)?;
            scene.path_numbers.push(number);
        }
        control.checkpoint().map_err(stopped)?;
        scene.shapes.push(shape);
        scene.shapes_serials.push(id.serial);
        Ok(())
    }
}
use crate::{Diagnostic, ErrorKind, LimitKind, Result};
/// Vec-reported reserved storage, excluding allocator bookkeeping and RSS.
/// Allocation history describes builder reserves and admitted owned payloads;
/// it does not reconstruct allocation calls made by parsers/providers before admission.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct MemoryStats {
    pub source_bytes: usize,
    pub live_bytes: usize,
    pub peak_live_bytes: usize,
    pub total_allocated_bytes: usize,
    pub allocation_count: usize,
}
pub(crate) fn bytes<T>(values: &Vec<T>) -> Result<usize> {
    values
        .capacity()
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)
}
pub(crate) fn add(a: usize, b: usize) -> Result<usize> {
    a.checked_add(b).ok_or_else(arithmetic)
}
pub(crate) fn arithmetic() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(LimitKind::Arithmetic),
        offset: 0,
    }
}
/// Reserve a replacement before transferring old values. Reject excess actual
/// capacity before moving anything. The caller supplies the available overlap budget.
pub(crate) fn reserve<T>(
    values: &mut Vec<T>,
    extra: usize,
    cap: usize,
    overlap: usize,
) -> Result<(usize, usize)> {
    let required = values.len().checked_add(extra).ok_or_else(arithmetic)?;
    if required > cap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::Nodes),
            offset: 0,
        });
    }
    if required <= values.capacity() {
        return Ok((0, 0));
    }
    let request = required
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)?;
    if request > overlap {
        return Err(Diagnostic {
            kind: ErrorKind::Limit(LimitKind::ReservedBytes),
            offset: 0,
        });
    }
    let mut replacement = Vec::new();
    let grown = values
        .capacity()
        .checked_mul(2)
        .unwrap_or(cap)
        .max(8)
        .min(cap)
        .max(required);
    let target = if grown
        .checked_mul(std::mem::size_of::<T>())
        .is_some_and(|n| n <= overlap)
    {
        grown
    } else {
        required
    };
