    svg_shape_error error = svg_shape_decode_source_with_bounds(
        (base_bytes){source, length}, &document, &diagnostic, &bounds);
    bool ok = error == SVG_SHAPE_ERROR_NONE &&
              raster_shape_render(&document, &tile, &diagnostic);
