        .capacity()
        .checked_mul(2)
        .unwrap_or(cap)
        .max(8)
        .min(cap)
        .max(required);
    let target = if grown
        .checked_mul(std::mem::size_of::<T>())
        .is_some_and(|n| n <= overlap)
